  --bg-hover: rgb(104,104,104);
  --text-primary: rgb(245,245,250);
  --text-secondary: rgba(255,255,255,0.66);
  --accent: rgb(17,17,17);
  --accent-secondary: rgb(203,203,203);
  --accent-hover: rgb(54,54,54);
  --bg-card: rgba(255,255,255,0.09);
  --bg-elevated: rgba(255,255,255,0.14);
  --border: rgba(255,255,255,0.09);
  --shadow-glow: rgb(17,17,17);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
@font-face {
  font-family: something; /* set name */
  src: url(data:@file/x-font-ttf;base64,)
}
html, body {
  height: 100%;
  font-family: "Margarine", system-ui;
  color: var(--text-primary);
  background: var(--bg-primary);
  overflow: hidden;
}

.app {
  display: grid;
  grid-template-columns: 280px 1fr;
  grid-template-rows: 1fr auto;
  height: 100vh;
  gap: 0;
  transition: var(--transition);
  position: relative;
  z-index: 1;
}

.app.sidebar-collapsed {
  grid-template-columns: 80px 1fr;
}

/* Sidebar */
.sidebar {
  grid-column: 1;
  grid-row: 1/3;
  background: rgba(10, 10, 20, 0.55);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  display: flex;
  flex-direction: column;
  padding: 24px 16px;
  transition: var(--transition);
  overflow: hidden;
  position: relative;
  border-right: 1px solid var(--border);
}

.sidebar.collapsed {
  padding: 24px 12px;
}

.sidebar.collapsed .brand-text,
.sidebar.collapsed .nav-text,
.sidebar.collapsed .playlist-name,
.sidebar.collapsed .playlist-count,
.sidebar.collapsed .btn-text,
.sidebar.collapsed .section-title {
  opacity: 0;
  width: 0;
  overflow: hidden;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 32px;
  cursor: pointer;
  padding: 8px;
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.brand:hover {
  background: rgba(255, 255, 255, 0.08);
}

.logo {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  color: var(--bg-primary);
  font-size: 20px;
  flex-shrink: 0;
  transition: var(--transition-bounce);
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  box-shadow: 0 4px 20px rgba(var(--shadow-glow), 0.5);
}

.brand:hover .logo {
  transform: scale(1.05) rotate(-5deg);
  box-shadow: 0 6px 24px rgba(var(--shadow-glow), 0.5);
}

.brand-text {
  transition: var(--transition);
  white-space: nowrap;
}

.brand-title {
  font-weight: 800;
  font-size: 22px;
  letter-spacing: -0.5px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.brand-sub {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  font-weight: 600;
}

.nav {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 24px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 14px;
  position: relative;
  border: 1px solid transparent;
}

.nav-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 0;
  background: linear-gradient(180deg, var(--accent) 0%, var(--accent-secondary) 100%);
  border-radius: 0 3px 3px 0;
  transition: height 0.3s ease;
}

.nav-item:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
  border-color: var(--border-hover);
}

.nav-item-click {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 14px;
  position: relative;
  border: 1px solid transparent;
}

.nav-item-click::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 0;
  background: linear-gradient(180deg, var(--accent) 0%, var(--accent-secondary) 100%);
  border-radius: 0 3px 3px 0;
  transition: height 0.3s ease;
}

.nav-item-click:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
  border-color: var(--border-hover);
}

.nav-item.active {
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.06);
  border-color: var(--border);
}

.nav-item.active::before {
  height: 60%;
}

.nav-icon {
  font-size: 20px;
  width: 24px;
  text-align: center;
  flex-shrink: 0;
  filter: grayscale(0.3);
  transition: var(--transition);
}

.nav-item:hover .nav-icon,
.nav-item.active .nav-icon {
  filter: grayscale(0);
  transform: scale(1.1);
}

.nav-text {
  white-space: nowrap;
  transition: var(--transition);
}

.divider {
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, var(--border) 50%, transparent 100%);
  margin: 20px 0;
}

.sidebar-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

/* Merged section-title rules */
.section-title {
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  font-weight: 700;
  padding: 0 16px;
  transition: var(--transition);
  white-space: nowrap;
}

/* Adjustments for sidebar specific titles */
.sidebar .section-title {
  font-size: 10px;
}

input {
  font-family: "Margarine", system-ui !important;
}

.btn {
  padding: 12px 18px;
  font-family: "Margarine", system-ui !important;
  font-weight: 400;
  font-style: normal;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  font-weight: 600;
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: center;
  white-space: nowrap;
  position: relative;
  overflow: hidden;
}

.btn::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
  transition: left 0.5s;
}

.btn:hover::before {
  left: 100%;
}

.btn.primary {
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  color: var(--bg-primary);
  box-shadow: 0 4px 16px rgba(var(--shadow-glow), 0.5);
}

.btn.primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(var(--shadow-glow), 0.5);
}

.btn.secondary {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  color: var(--text-primary);
}

.btn.secondary:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border-hover);
  transform: translateY(-1px);
}

.playlists-container {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-right: 8px;
}

.playlists-container::-webkit-scrollbar {
  width: 4px;
}

.playlists-container::-webkit-scrollbar-track {
  background: transparent;
}

.playlists-container::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.06);
  border-radius: 2px;
}

.playlists-container::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.08);
}

.playlist-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  position: relative;
  border: 1px solid transparent;
}

.playlist-item:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border);
}

.playlist-item.active {
  background: rgba(255, 255, 255, 0.06);
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.playlist-icon {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, var(--bg-tertiary) 0%, var(--bg-hover) 100%);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex-shrink: 0;
  border: 1px solid var(--border);
}

.playlist-info {
  flex: 1;
  min-width: 0;
  transition: var(--transition);
}

.playlist-name {
  font-weight: 600;
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: var(--transition);
}

.playlist-count {
  font-size: 11px;
  color: var(--text-muted);
  transition: var(--transition);
}

.playlist-actions {
  display: flex;
  gap: 4px;
  opacity: 0;
  transition: var(--transition);
}

.playlist-item:hover .playlist-actions {
  opacity: 1;
}

.playlist-btn {
  padding: 6px 10px;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: var(--transition);
  font-size: 14px;
}

.playlist-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
}

/* Main Content */
.main {
  background: rgba(10, 10, 20, 0.45);
  grid-column: 2;
  grid-row: 1;
  overflow-y: auto;
  padding: 24px 32px;
  position: relative;
}

.main::-webkit-scrollbar {
  width: 8px;
}

.main::-webkit-scrollbar-track {
  background: transparent;
}

.main::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.06);
  border-radius: 4px;
}

.main::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.08);
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
  position: relative;
  z-index: 1;
}

.search-container {
  position: relative;
  flex: 1;
  max-width: 420px;
}

.search-input {
  width: 100%;
  padding: 14px 20px 14px 48px;
  background: rgba(10, 10, 20, 0.3);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  color: var(--text-primary);
  font-size: 14px;
  transition: var(--transition);
  backdrop-filter: blur(10px);
}

.search-input:focus {
  outline: none;
  background: rgba(255, 255, 255, 0.06);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--shadow-glow), rgba(var(--shadow-glow), 0.5);
}

.search-icon {
  position: absolute;
  left: 18px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  font-size: 18px;
  transition: var(--transition);
}

.search-input:focus + .search-icon {
  color: var(--accent);
}

.user-profile {
  display: flex;
  align-items: center;
  gap: 12px;
}

.settings-btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: rgba(10, 10, 20, 0.3);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
  color: var(--text-secondary);
  font-size: 18px;
  position: relative;
  overflow: hidden;
}

.settings-btn::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  opacity: 0;
  transition: var(--transition);
}

.settings-btn:hover {
  border-color: var(--accent);
  color: var(--text-primary);
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(var(--shadow-glow), 0.5);
}

.settings-btn:hover::after {
  opacity: 0.1;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.view-all {
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  transition: var(--transition);
  padding: 8px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}

.view-all:hover {
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border-hover);
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 24px;
  margin-bottom: 48px;
}

.card {
  background: rgba(10, 10, 20, 0.4);
  border-radius: var(--radius-lg);
  padding: 16px;
  cursor: pointer;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border);
}

.card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 0%, var(--shadow-glow) 100%);
  opacity: 0;
  transition: var(--transition);
}

.card:hover {
  background: var(--bg-elevated);
  transform: translateY(-6px);
  box-shadow: var(--shadow), rgba(var(--shadow-glow), 0.5);
  border-color: var(--border-hover);
}

.card:hover::before {
  opacity: 1;
}

.card-img {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
  border-radius: var(--radius-md);
  margin-bottom: 14px;
  background: rgba(255, 255, 255, 0.06);
  transition: var(--transition);
  border: 1px solid var(--border);
}

.card:hover .card-img {
  transform: scale(1.02);
}

.card-title {
  font-weight: 700;
  font-size: 14px;
  margin-bottom: 6px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.card-subtitle {
  font-size: 12px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.card-play {
  position: absolute;
  bottom: 90px;
  right: 20px;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  color: var(--bg-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  opacity: 0;
  transform: translateY(10px) scale(0.8);
  transition: var(--transition-bounce);
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(var(--shadow-glow), 0.5);
  border: 2px solid rgba(255,255,255,0.1);
}

.card:hover .card-play {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.card-play:hover {
  transform: scale(1.1);
  box-shadow: 0 12px 32px rgba(var(--shadow-glow), 0.5);
}

/* Queue Container */
.queue-container {
  background: rgba(10, 10, 20, 0.4);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 24px;
  border: 1px solid var(--border);
  position: relative;
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  margin: 0 auto 24px auto !important;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.queue-container::before {
  content: '';
  position: absolute;
  top: 0;
  left: 24px;
  right: 24px;
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, var(--accent) 50%, transparent 100%);
  opacity: 0.3;
}

.queue-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.queue-title {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.3px;
}

.queue-controls {
  display: flex;
  gap: 10px;
}

.queue-btn {
  padding: 10px 18px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  transition: var(--transition);
}

.queue-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border-hover);
  color: var(--text-primary);
  transform: translateY(-1px);
}

.queue-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100% !important;
  max-height: 50vh !important;
  overflow-y: auto !important;
}

.queue-list::-webkit-scrollbar {
  width: 6px;
}

.queue-list::-webkit-scrollbar-track {
  background: transparent;
}

.queue-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
}

.queue-item {
  display: grid;
  grid-template-columns: 44px 52px 1fr auto 70px;
  gap: 14px;
  align-items: center;
  padding: 10px 14px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  border: 1px solid transparent;
  width: 100% !important;
  box-sizing: border-box !important;
}

.queue-item:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border);
}

.queue-item.playing {
  background: rgba(255, 255, 255, 0.06);
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.queue-item.playing .queue-number {
  color: var(--accent);
  font-weight: 700;
}

.queue-number {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.queue-img {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  transition: var(--transition);
}

.queue-item:hover .queue-img {
  transform: scale(1.05);
}

.queue-info {
  min-width: 0;
}

.queue-track-title {
  font-weight: 600;
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-bottom: 4px;
}

.queue-track-artist {
  font-size: 12px;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.queue-actions {
  display: flex;
  gap: 6px;
  opacity: 0;
  transition: var(--transition);
}

.queue-item:hover .queue-actions {
  opacity: 1;
}

.queue-action-btn {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  transition: var(--transition);
}

.queue-action-btn:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg-primary);
  transform: scale(1.1);
}

.queue-duration {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

/* Player Bar */
.player {
  grid-column: 1/3;
  grid-row: 2;
  background: rgba(10, 10, 20, 0.6);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid var(--border);
  padding: 16px 28px;
  display: flex;
  align-items: center;
  gap: 24px;
  height: 90px;
  position: relative;
}

.player::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, var(--accent) 50%, transparent 100%);
  opacity: 0.5;
}

.player-track {
  display: flex;
  align-items: center;
  gap: 14px;
  flex: 0 1 240px !important;
  min-width: 0 !important;
}

.player-embed {
  display: none;
}

.player-img {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  box-shadow: 0 4px 16px rgba(0,0,0,0.3);
  transition: var(--transition);
}

.player-img:hover {
  transform: scale(1.05);
}

.player-info {
  min-width: 0;
  flex: 1;
}

.player-title {
  font-weight: 700;
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-bottom: 4px;
}

.player-artist {
  font-size: 12px;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.player-controls-section {
  flex: 2 !important;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
  min-width: 200px !important;
}

.player-controls {
  display: flex;
  align-items: center;
  gap: 20px;
}

.player-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  transition: var(--transition);
  position: relative;
}

.player-btn:hover {
  color: var(--text-primary);
  transform: scale(1.1);
}

.player-btn.play-pause {
  width: 48px;
  height: 48px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  color: var(--bg-primary);
  font-size: 20px;
  box-shadow: 0 4px 16px rgba(var(--shadow-glow), 0.5);
}

.player-btn.play-pause:hover {
  transform: scale(1.1);
  box-shadow: 0 8px 24px rgba(var(--shadow-glow), 0.5);
}

.progress-section {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  max-width: 600px;
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-bottom: 28px;
}

.stats-card {
  background: rgba(255, 255, 255, 0.06);
  padding: 24px;
  border-radius: var(--radius-lg);
  text-align: center;
  border: 1px solid var(--border);
  transition: var(--transition);
}

.stats-card:hover {
  transform: translateY(-4px);
  border-color: var(--border-hover);
  box-shadow: var(--shadow);
}

.stats-card h4 {
  font-size: 36px;
  color: var(--accent);
  margin-bottom: 8px;
  font-weight: 800;
  text-shadow: 0 0 20px rgba(var(--shadow-glow), 0.5);
}

.stats-card p {
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.top-tracks-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.top-track-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
  transition: var(--transition);
  cursor: pointer;
}

.top-track-item:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border-hover);
  transform: translateX(4px);
}

.top-track-item img {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  border: 1px solid var(--border);
}

.top-track-info {
  flex: 1;
}

.top-track-info h5 {
  font-size: 14px;
  margin-bottom: 4px;
  font-weight: 600;
}

.top-track-info p {
  font-size: 12px;
  color: var(--text-muted);
}

.top-track-plays {
  font-size: 14px;
  color: var(--accent);
  font-weight: 700;
  padding: 6px 12px;
  background: rgba(var(--shadow-glow), 0.5);
  border-radius: var(--radius-sm);
}

.time {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
  min-width: 42px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.progress-bar {
  flex: 1;
  height: 5px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent-secondary) 100%);
  border-radius: 3px;
  transition: width 0.1s linear;
  position: relative;
}

.progress-fill::after {
  content: '';
  position: absolute;
  right: -8px;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  background: var(--text-primary);
  border-radius: 50%;
  opacity: 0;
  transition: opacity 0.2s, transform 0.2s;
  box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

.progress-bar:hover .progress-fill::after {
  opacity: 1;
}

.player-right {
  display: flex;
  align-items: center;
  gap: 14px;
  flex: 0 1 200px !important;
  min-width: 100px !important;
  justify-content: flex-end;
}

.volume-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  transition: var(--transition);
}

.volume-btn:hover {
  color: var(--text-primary);
  transform: scale(1.1);
}

.volume-slider-container {
  display: flex;
  align-items: center;
  flex: 1;
  max-width: 120px;
}

.volume-slider {
  width: 100%;
  height: 5px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.volume-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent-secondary) 100%);
  border-radius: 3px;
  transition: width 0.1s linear;
}

/* Modal */
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0,0,0,0.8);
  backdrop-filter: blur(8px);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: fadeIn 0.2s;
  padding: 20px;
}

.modal-overlay.active {
  display: flex;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.modal {
  background: rgba(10, 10, 20, 0.4);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 500px;
  width: 100%;
  max-height: 85vh;
  overflow-y: auto;
  animation: slideUp 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  position: relative;
}

.modal::before {
  content: '';
  position: absolute;
  top: 0;
  left: 32px;
  right: 32px;
  height: 2px;
  background: linear-gradient(90deg, transparent 0%, var(--accent) 50%, transparent 100%);
  opacity: 0.5;
}

@keyframes slideUp {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}

.modal-title {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.modal-close {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 18px;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
  border-color: var(--border-hover);
  transform: rotate(90deg);
}

.form-group {
  margin-bottom: 20px;
}

.form-label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.form-input {
  width: 100%;
  padding: 14px 18px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 14px;
  transition: var(--transition);
}

.form-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(var(--shadow-glow), 0.5);
}

.form-input::placeholder {
  color: var(--text-muted);
}

/* Toast */
.toast {
  position: fixed;
  bottom: 110px;
  left: 50%;
  transform: translateX(-50%) translateY(100px);
  background: rgba(10, 10, 20, 0.4);
  border: 1px solid var(--border);
  padding: 16px 28px;
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: var(--shadow);
  z-index: 2000;
  opacity: 0;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  backdrop-filter: blur(10px);
  visibility: hidden;
}

.toast.show {
  transform: translateX(-50%) translateY(0);
  opacity: 1;
  visibility: visible;
}

.toast-icon {
  font-size: 20px;
}

.toast-message {
  font-size: 14px;
  font-weight: 600;
}

/* Empty State */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 64px 24px;
  text-align: center;
  color: var(--text-muted);
}

.empty-icon {
  font-size: 64px;
  margin-bottom: 16px;
  opacity: 0.5;
  filter: grayscale(0.5);
}

.empty-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--text-secondary);
}

.empty-subtitle {
  font-size: 14px;
}

input[type="file"] {
  display: none;
}

/* Responsive */
@media (max-width: 1024px) {
  .app {
    grid-template-columns: 80px 1fr;
  }

  .sidebar {
    padding: 24px 12px;
  }

  .brand-text,
  .nav-text,
  .playlist-name,
  .playlist-count,
  .btn-text,
  .section-title {
    opacity: 0;
    width: 0;
  }

  .player {
    flex-wrap: wrap;
    height: auto;
    padding: 16px 12px !important;
    gap: 12px !important;
  }

  .player-track {
    min-width: 0;
    flex: 1;
  }

  .player-controls-section {
    order: 3;
    width: 100%;
    margin-top: 8px;
  }

  .player-right {
    min-width: 0;
    flex: 0;
  }

  .volume-slider-container {
    display: none;
  }
}

@media (max-width: 768px) {
  .queue-container {
    padding: 16px !important;
    margin-bottom: 16px !important;
  }

  .queue-item {
    grid-template-columns: 36px 44px 1fr auto 60px !important;
    gap: 8px !important;
    padding: 8px 10px !important;
  }

  .queue-img {
    width: 44px !important;
    height: 44px !important;
  }

  .queue-number {
    font-size: 12px !important;
  }

  .queue-track-title {
    font-size: 13px !important;
  }

  .queue-track-artist {
    font-size: 11px !important;
  }

  .queue-duration {
    font-size: 11px !important;
    min-width: 50px !important;
  }

  .queue-actions {
    opacity: 1 !important;
  }

  .queue-action-btn {
    width: 28px !important;
    height: 28px !important;
    font-size: 12px !important;
  }
}

@media (max-width: 480px) {
  .queue-item {
    grid-template-columns: 32px 40px 1fr auto 50px !important;
    gap: 6px !important;
  }

  .queue-img {
    width: 40px !important;
    height: 40px !important;
  }

  .queue-duration {
    display: none !important;
  }
}

/* Color Swatches */
.color-swatch {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  cursor: pointer;
  border: 2px solid var(--border);
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.color-swatch::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,255,255,0.2) 0%, transparent 50%);
  opacity: 0;
  transition: var(--transition);
}

.color-swatch:hover {
  transform: scale(1.15);
  border-color: var(--accent);
}

.color-swatch:hover::after {
  opacity: 1;
}

.color-swatch.active {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(var(--shadow-glow), 0.5);
  transform: scale(1.1);
}

.theme-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(44px, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}

.import-controls {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.settings-section {
  margin-bottom: 28px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.settings-section:last-child {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.settings-section-title {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text-primary);
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Toggle switches (Album Art Background, Performance Mode, etc.) */
.setting-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 0;
}

.setting-toggle-row:not(:last-child) {
  border-bottom: 1px solid var(--border);
}

.setting-toggle-label {
  font-size: 14px;
  color: var(--text-primary);
}

.toggle-slider {
  position: relative;
  flex-shrink: 0;
  width: 42px;
  height: 24px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-tertiary);
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.toggle-slider:hover {
  border-color: var(--border-hover);
}

.toggle-slider:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.toggle-slider .slider-thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--text-secondary);
  transition: transform 0.2s ease, background 0.2s ease;
}

.toggle-slider[aria-checked="true"] {
  background: var(--accent);
  border-color: var(--accent);
}

.toggle-slider[aria-checked="true"] .slider-thumb {
  background: #fff;
  transform: translateX(18px);
}

/* Performance Mode: strip out the expensive GPU-heavy effects
   (backdrop blur, filter blur, box-shadows, transitions/animations)
   for low-end devices. Kept last so !important always wins. */
body.performance-mode * {
  backdrop-filter: none !important;
  background: none;
  -webkit-backdrop-filter: none !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
  --ios-blur: blur(0px) !important;
  --glass-bg: var(--glass-tint) !important; 
  --glass-bg-soft: var(--glass-tint) !important; 
}

body.performance-mode *,
body.performance-mode *::before,
body.performance-mode *::after {
  transition: none !important;
  animation: none !important;
  scroll-behavior: auto !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
  --ios-blur: blur(0px) !important;
}

body.performance-mode .progress-fill,
body.performance-mode .volume-fill,
body.performance-mode .player-btn.play-pause {
  background: var(--accent-secondary) !important;
}

body.performance-mode .full-lyrics-player {
  background: var(--bg-primary) !important;
}

body.performance-mode .yc-panel {
  background: var(--bg-primary) !important;
}

body.performance-mode .yc-announce {
  position: fixed; top: 0; left: 0; right: 0;
  z-index: 2000; display: none;
  padding: 14px 18px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  color: #0a0a0f;
  box-shadow: 0 8px 32px rgba(0,0,0,0.45);
  animation: ycDrop 0.35s cubic-bezier(0.4,0,0.2,1);
}
body.performance-mode .yc-announce.show { display: block; }

body.performance-mode .yc-announce-inner {
  max-width: 900px; margin: 0 auto; display: flex; align-items: center; gap: 14px;
}
body.performance-mode .yc-announce-label {
  font-size: 10.5px; font-weight: 900; letter-spacing: 1.4px; text-transform: uppercase;
  opacity: 0.65; flex-shrink: 0;
}
body.performance-mode .yc-announce-text { flex: 1; font-size: 15px; font-weight: 700; line-height: 1.4; }
body.performance-mode .yc-announce-close {
  background: rgba(0,0,0,0.18); border: none; color: inherit; cursor: pointer;
  border-radius: 8px; padding: 5px 11px; font-weight: 800; font-size: 14px; flex-shrink: 0;
}

body.performance-mode .yc-send {
  background: var(--accent-secondary) !important;
}

body.performance-mode .full-lyrics-progress {
  flex: 1;
  height: 4px;
  border-radius: 999px;
  background: rgba(255,255,255,.16);
  cursor: pointer;
  overflow: hidden;
}

body.performance-mode .full-lyrics-progress-fill {
  width: 0%;
  height: 100%;
  background: var(--text-primary);
  border-radius: inherit;
  transition: width .08s linear;
}

body.performance-mode .hero-art {
  position: relative;
  z-index: 1;
  width: 118px;
  aspect-ratio: 1;
  border-radius: 26px;
  background:
    radial-gradient(circle at 32% 26%, rgba(255,255,255,0.9), transparent 14%),
    linear-gradient(145deg, #ff2d55, #ff7a59 55%, #6e5cff);
  box-shadow: 0 22px 55px var(--accent), inset 0 1px 0 var(--accent-secondary);
  background-size: cover;
  background-position: center;
}

body.performance-mode .result-thumb {
  width: 100px;
  height: 70px;
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.08);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: var(--text-muted);
  background-size: cover;
  background-position: center;
  border: 1px solid var(--border);
} 

body.performance-mode .modal {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  max-width: 100% !important;
  width: 100% !important;
  height: 100% !important;
  max-height: 100% !important;
  right: 0px !important;
  left: 0px !important;
  padding: 10px !important;
}

body.performance-mode .modal::before {
  opacity: 1 !important;
  border: none !important;
  box-shadow: none !important;
  left: 0px !important;
  right: 0px !important;
  padding: 0px !important;
}

body.performance-mode .modal-overlay {
  background: var(--accent) !important;
  backdrop-filter: none !important;
}

/* Search Panel */
.search-panel {
  background: rgba(10, 10, 20, 0.4);
  border-radius: var(--radius-lg);
  padding: 32px;
  margin-bottom: 32px;
  border: 1px solid var(--border);
  position: relative;
}

.search-panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 32px;
  right: 32px;
  height: 2px;
  background: linear-gradient(90deg, transparent 0%, var(--accent) 50%, transparent 100%);
  opacity: 0.3;
}

.search-panel-header {
  display: flex;
  gap: 14px;
  margin-bottom: 24px;
}

.search-panel-input {
  flex: 1;
  padding: 14px 20px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 14px;
  transition: var(--transition);
}

.search-panel-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(var(--shadow-glow), 0.5);
}

.search-results {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.result-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  transition: var(--transition);
  border: 1px solid transparent;
}

.result-item:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border);
  transform: translateX(4px);
}

.result-thumb {
  width: 100px;
  height: 70px;
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.08);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: var(--text-muted);
  background-size: cover;
  background-position: center;
  border: 1px solid var(--border);
}

.result-meta {
  flex: 1;
  min-width: 0;
}

.result-title {
  font-weight: 700;
  font-size: 15px;
  margin-bottom: 6px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.result-author {
  font-size: 13px;
  color: var(--text-secondary);
}

/* Track Select */
.track-select-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 300px;
  overflow-y: auto;
}

.track-select-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  border: 2px solid transparent;
}

.track-select-item:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--border);
}

.track-select-item.selected {
  border-color: var(--accent);
  background: rgba(var(--shadow-glow), 0.5);
}

.checkbox {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  flex-shrink: 0;
  background: rgba(10, 10, 20, 0.3);
}

.track-select-item.selected .checkbox {
  background: var(--accent);
  border-color: var(--accent);
}

.checkbox::after {
  content: '✓';
  color: var(--bg-primary);
  font-weight: 800;
  font-size: 14px;
  opacity: 0;
  transition: var(--transition);
}

.track-select-item.selected .checkbox::after {
  opacity: 1;
}

.modal-footer {
  padding-top: 20px;
  border-top: 1px solid var(--border);
  display: flex;
  gap: 12px;
  justify-content: flex-end;
}

.modal.wide {
  max-width: 700px;
}

/* Lyrics Panel */
.lyrics-panel {
  position: fixed;
  right: 0;
  top: 0;
  width: 380px;
  height: 100vh;
  background: rgba(10, 10, 20, 0.3);
  border-left: 1px solid var(--border);
  transform: translateX(100%);
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 102;
  display: flex;
  flex-direction: column;
  box-shadow: -8px 0 32px rgba(0,0,0,0.4);
  scrollbar-width: none; 
}

.lyrics-panel.open {
  transform: translateX(0);
    scrollbar-width: none; 
}

body.lyrics-open .app {
  margin-right: 380px;
    scrollbar-width: none; 

}

.lyrics-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px;
  border-bottom: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
    scrollbar-width: none; 

}

.lyrics-title {
  font-size: 18px;
  font-weight: 800;
    scrollbar-width: none; 

  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 10px;
}

.lyrics-title::before {
  content: '🎤';
  font-size: 20px;
    scrollbar-width: none; 

}

.lyrics-close {
  width: 36px;
    scrollbar-width: none; 

  height: 36px;
  border-radius: var(--radius-md);
  background: rgba(10, 10, 20, 0.4);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  font-size: 16px;
}

.lyrics-close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
  border-color: var(--border-hover);
  transform: rotate(90deg);
    scrollbar-width: none; 

}

.lyrics-content {
  flex: 1;
    scrollbar-width: none; 

  overflow-y: auto;
  padding: 24px;
  scroll-behavior: smooth;
}

.lyrics-content::-webkit-scrollbar {
  width: 6px;
    scrollbar-width: none; 

}

.lyrics-content::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
    scrollbar-width: none; 

}

.lyrics-line {
  padding: 14px 18px;
  margin-bottom: 10px;
  border-radius: var(--radius-md);
  font-size: 15px;
  line-height: 1.7;
  color: var(--text-secondary);
  transition: all 0.3s ease;
    scrollbar-width: none; 

  cursor: pointer;
  border-left: 3px solid transparent;
  background: transparent;
}

.lyrics-line:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
    scrollbar-width: none; 

  border-left-color: var(--border);
}

.lyrics-line.active {
  color: var(--accent);
  background: rgba(var(--shadow-glow), 0.5);
    scrollbar-width: none; 

  border-left-color: var(--accent);
  font-weight: 700;
  transform: scale(1.02);
  box-shadow: 0 4px 16px rgba(var(--shadow-glow), 0.5);
}

.lyrics-line.passed {
  color: var(--text-muted);
  opacity: 0.5;
    scrollbar-width: none; 

}

.lyrics-empty {
  display: flex;
    scrollbar-width: none; 

  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-muted);
  text-align: center;
  padding: 40px;
}

.lyrics-empty-icon {
  font-size: 56px;
  margin-bottom: 20px;
  opacity: 0.4;
    scrollbar-width: none; 

}

.lyrics-toggle-btn {
  position: fixed;
  right: 24px;
  bottom: 190px;
  width: 56px;
  height: 56px;
    scrollbar-width: none; 

  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  color: var(--bg-primary);
  border: none;
  cursor: pointer;
  font-size: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 20px rgba(var(--shadow-glow), 0.5);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 99;
}

body.effects-open .lyrics-toggle-btn, body.lyrics-open .lyrics-toggle-btn {
  left: 13px;
  right: auto;
    scrollbar-width: none; 

}

.lyrics-toggle-btn:hover {
  transform: scale(1.1) rotate(10deg);
  box-shadow: 0 8px 28px rgba(var(--shadow-glow), 0.5);
    scrollbar-width: none; 

}

.lyrics-toggle-btn.active {
  background: rgba(255, 255, 255, 0.06);
  color: var(--accent);
  border: 2px solid var(--accent);
    scrollbar-width: none; 
}

.lyrics-loading {
  display: flex;
  flex-direction: column;
    scrollbar-width: none; 

  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-secondary);
}

.lyrics-spinner {
  width: 44px;
  height: 44px;
  border: 3px solid var(--bg-tertiary);
  border-top-color: var(--accent);
  border-radius: 50%;
    scrollbar-width: none; 

  animation: spin 1s linear infinite;
  margin-bottom: 16px;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.lyrics-error {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
    scrollbar-width: none; 

  color: #ff6b6b;
  text-align: center;
  padding: 40px;
}

.lyrics-not-found {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-muted);
    scrollbar-width: none; 

  text-align: center;
  padding: 40px;
}

/* Effects Panel */
.effects-panel {
  position: fixed;
  right: 0;
  top: 0;
  width: 380px;
  height: 100vh;
  background: rgba(10, 10, 20, 0.3);
  border-left: 1px solid var(--border);
  z-index: 100;
  transition: right 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  padding: 28px;
  overflow-y: auto;
  box-shadow: -8px 0 32px rgba(0,0,0,0.4);
  right: -380px;
}

.effects-panel.open {
  right: 0;
}

.effects-toggle-btn {
  position: fixed;
  right: 24px;
  bottom: 120px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(10, 10, 20, 0.4);
  border: 1px solid var(--border);
  color: var(--text-primary);
  cursor: pointer;
  font-size: 22px;
  z-index: 99;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}

body.effects-open .effects-toggle-btn, body.lyrics-open .effects-toggle-btn {
  left: 15px;
  right: auto;
}

.effects-toggle-btn:hover {
  transform: scale(1.1) rotate(10deg);
  box-shadow: 0 8px 28px rgba(var(--shadow-glow), 0.5);
    scrollbar-width: none; 
}

.effects-toggle-btn.active {
  background: rgba(255, 255, 255, 0.06);
  color: var(--accent);
  border: 2px solid var(--accent);
  scrollbar-width: none; 
}

body.effects-open .app {
  margin-right: 380px;
}


body.lyrics-open .effects-panel.open {
  right: 380px;
}

.eq-slider {
  margin-bottom: 20px;
}

.eq-slider label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 8px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.eq-slider input[type="range"] {
  width: 100%;
  height: 8px;
  -webkit-appearance: none;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 4px;
  outline: none;
  border: 1px solid var(--border);
}

.eq-slider input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  border-radius: 50%;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(var(--shadow-glow), 0.5);
  transition: var(--transition);
}

.eq-slider input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.2);
  box-shadow: 0 4px 12px rgba(var(--shadow-glow), 0.5);
}

/* Crossfade */
.crossfade-control {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 16px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}

.crossfade-control input[type="range"] {
  flex: 1;
  height: 8px;
  -webkit-appearance: none;
  background: rgba(10, 10, 20, 0.4);
  border-radius: 4px;
  outline: none;
}

.crossfade-control input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
  border-radius: 50%;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(var(--shadow-glow), 0.5);
}

/* BLOB BACKGROUND SYSTEM */
html {  }
body { background: var(--bg-primary); }

#artBg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: visible;
}

.art-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0;
  transition: background 1.2s ease, opacity 0.6s ease;
  will-change: transform;
}

.art-blob.visible { opacity: 0.45; }

.art-blob:nth-child(1) {
  width: 80vw; height: 80vw;
  top: -20%; left: -10%;
  animation: blobA 20s ease-in-out infinite alternate;
}

.art-blob:nth-child(2) {
  width: 75vw; height: 75vw;
  bottom: -10%; right: -10%;
  animation: blobB 25s ease-in-out infinite alternate;
}

.art-blob:nth-child(3) {
  width: 55vw; height: 55vw;
  top: 20%; left: 30%;
  animation: blobC 17s ease-in-out infinite alternate;
}

.art-blob:nth-child(4) {
  width: 60vw; height: 60vw;
  bottom: 0%; left: 0%;
  animation: blobD 13s ease-in-out infinite alternate;
}

.art-blob:nth-child(5) {
  width: 65vw; height: 65vw;
  top: -5%; right: 5%;
  animation: blobE 22s ease-in-out infinite alternate;
}

.art-blob:nth-child(6) {
  width: 50vw; height: 50vw;
  bottom: 5%; left: 30%;
  animation: blobF 11s ease-in-out infinite alternate;
}

@keyframes blobA {
  0%   { transform: translate(0,0) scale(1);       border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
  50%  { transform: translate(6vw,10vh) scale(1.1); border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%; }
  100% { transform: translate(-4vw,6vh) scale(0.95);border-radius: 50% 60% 40% 70% / 40% 50% 60% 50%; }
}

@keyframes blobB {
  0%   { transform: translate(0,0) scale(1);        border-radius: 40% 60% 60% 40% / 40% 30% 70% 60%; }
  50%  { transform: translate(-7vw,-6vh) scale(1.08);border-radius: 60% 40% 30% 70% / 50% 70% 40% 50%; }
  100% { transform: translate(5vw,-9vh) scale(1.12); border-radius: 50% 50% 40% 60% / 60% 40% 50% 40%; }
}

@keyframes blobC {
  0%   { transform: translate(0,0) scale(1);        border-radius: 50% 50% 60% 40% / 40% 60% 50% 50%; }
  50%  { transform: translate(9vw,-7vh) scale(0.88); border-radius: 40% 60% 40% 60% / 60% 40% 60% 40%; }
  100% { transform: translate(-6vw,5vh) scale(1.08); border-radius: 60% 40% 50% 50% / 50% 60% 40% 60%; }
}

@keyframes blobD {
  0%   { transform: translate(0,0) scale(1);         border-radius: 70% 30% 50% 50% / 40% 60% 40% 60%; }
  50%  { transform: translate(8vw,12vh) scale(1.15);  border-radius: 40% 60% 30% 70% / 60% 30% 60% 40%; }
  100% { transform: translate(-5vw,-8vh) scale(0.9);  border-radius: 50% 50% 70% 30% / 30% 70% 50% 50%; }
}

@keyframes blobE {
  0%   { transform: translate(0,0) scale(1);          border-radius: 30% 70% 40% 60% / 60% 40% 70% 30%; }
  50%  { transform: translate(-10vw,5vh) scale(0.92); border-radius: 60% 40% 60% 40% / 40% 60% 30% 70%; }
  100% { transform: translate(7vw,-11vh) scale(1.1);  border-radius: 50% 60% 30% 70% / 70% 30% 60% 40%; }
}

@keyframes blobF {
  0%   { transform: translate(0,0) scale(1);          border-radius: 60% 40% 70% 30% / 50% 50% 40% 60%; }
  50%  { transform: translate(-9vw,7vh) scale(1.2);   border-radius: 30% 70% 50% 50% / 60% 40% 70% 30%; }
  100% { transform: translate(4vw,-5vh) scale(0.85);  border-radius: 70% 30% 40% 60% / 40% 70% 30% 60%; }
}

/* Animations */
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

@keyframes messageSlide {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes typingBounce {
  0%, 80%, 100% { transform: scale(0); }
  40% { transform: scale(1); }
}

@keyframes chatTypingBounce {
  0%, 80%, 100% { transform: scale(0); }
  40% { transform: scale(1); }
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.06);
  border-radius: 5px;
  border: 2px solid var(--bg-primary);
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.08);
}

::selection {
  background: rgba(var(--shadow-glow), 0.3);
  color: var(--text-primary);
}

/* Responsive Media Queries */
@media (max-width: 1200px) {
  .lyrics-panel,
  .effects-panel {
    width: 340px;
  }

  body.lyrics-open .app,
  body.effects-open .app {
    margin-right: 340px;
  }

  body.lyrics-open .lyrics-toggle-btn,
  body.effects-open .effects-toggle-btn {
    right: 364px;
  }
}

@media (max-width: 1024px) {
  .lyrics-panel,
  .effects-panel {
    width: 100%;
    z-index: 200;
    right: -100%;
  }

  body.lyrics-open .app,
  body.effects-open .app {
    margin-right: 0;
    filter: blur(3px);
    pointer-events: none;
  }

  body.lyrics-open .lyrics-toggle-btn,
  body.effects-open .effects-toggle-btn {
    right: 24px;
    bottom: auto;
    top: 20px;
  }
}

@media (max-width: 900px) {
  body.lyrics-open .app,
  body.effects-open .app {
    transform: scale(0.98);
    transform-origin: left center;
  }
}

@media (max-width: 768px) {
  .lyrics-panel,
  .effects-panel {
    width: 100%;
    right: -100%;
  }

  .lyrics-panel.open,
  .effects-panel.open {
    right: 0;
  }

  body.lyrics-open .lyrics-toggle-btn,
  body.lyrics-open .effects-toggle-btn,
  body.effects-open .lyrics-toggle-btn,
  body.effects-open .effects-toggle-btn {
    right: 24px;
  }
}

