</svg></button>
        <button class="player-btn" onclick="toggleRepeat()" id="repeatBtn"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
  <polyline points="17 1 21 5 17 9"></polyline>
