            <button class="btn secondary lyrics-popout-btn" style="padding:2px 8px;font-size:11px;" onclick="openLyricsPopout()" title="Pop out lyrics into a floating window">⧉ Pop out</button>
          </div>
          <div class="player-embed-lyrics-content" id="playerEmbedLyricsContent">
    <div class="lyrics-empty">Play a song to see lyrics</div>
  </div>
        </div>
        <div class="player-embed-face player-embed-eq" id="playerEmbedEqFace">
          <div class="player-embed-header">
            <span class="player-embed-label">🎛️ Equalizer</span>
          </div>
          <div class="player-embed-eq-content">
            <div class="eq-slider">
              <label>Bass <span id="bassValueEmbed">0</span></label>
              <input type="range" min="-36" max="36" value="0" id="bassSliderEmbed" oninput="updateEQ('bass', this.value)">
            </div>
            <div class="eq-slider">
              <label>Mid <span id="midValueEmbed">0</span></label>
              <input type="range" min="-12" max="12" value="0" id="midSliderEmbed" oninput="updateEQ('mid', this.value)">
            </div>
            <div class="eq-slider">
              <label>Treble <span id="trebleValueEmbed">0</span></label>
              <input type="range" min="-12" max="12" value="0" id="trebleSliderEmbed" oninput="updateEQ('treble', this.value)">
            </div>
            <div class="eq-slider">
              <label>Speed <span id="speedValueEmbed">1</span></label>
              <input type="range" min="0.1" max="2" step="0.05" value="1" id="speedSliderEmbed" oninput="setPlaybackSpeed(this.value); document.getElementById('speedValueEmbed').innerHTML = this.value;">
            </div>
            <div class="eq-slider">
              <label>Crossfade <span id="crossfadeValue">5</span></label>
              <input type="range" min="0" max="10" value="5" id="crossfadeSliderEmbed" oninput="updateCrossfade(this.value)">
            </div>
            <div class="eq-slider">
              <label>Gain <span id="gainValueEmbed">100%</span></label>
              <input type="range" min="50" max="150" value="100" id="gainSliderEmbed" oninput="updateGain(this.value)">
            </div>
          </div>
        </div>
      </div>
