<!-- APPLE MUSIC-STYLE FULL-SCREEN LYRICS PLAYER -->
<div id="fullLyricsPlayer" class="full-lyrics-player" aria-hidden="true">
  <div class="full-lyrics-topbar">
    <button class="full-lyrics-close" type="button" onclick="closeFullLyricsPlayer()" aria-label="Close lyrics player" title="Close">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
        <line x1="18" y1="6" x2="6" y2="18"></line>
        <line x1="6" y1="6" x2="18" y2="18"></line>
      </svg>
    </button>
  </div>

  <div class="full-lyrics-main">
    <section class="full-lyrics-art-side">
      <img id="fullLyricsArt" class="full-lyrics-art" src="" alt="">
      <div class="full-lyrics-track-info">
        <div id="fullLyricsTitle" class="full-lyrics-title">No track playing</div>
        <div id="fullLyricsArtist" class="full-lyrics-artist">Select a track to play</div>
      </div>

      <div class="full-lyrics-controls">
        <div class="full-lyrics-progress-row">
          <span id="fullLyricsCurrentTime" class="full-lyrics-time">0:00</span>
          <div id="fullLyricsProgress" class="progress-bar" onclick="seekFullLyricsProgress(event)">
            <div id="fullLyricsProgressFill" class="full-lyrics-progress-fill"></div>
          </div>
          <span id="fullLyricsDuration" class="full-lyrics-time">0:00</span>
        </div>

        <div class="full-lyrics-buttons">
          <button class="btn secondary lyrics-fetch-btn" style="padding:2px 8px;font-size:11px;" onclick="fetchCurrentTrackLyrics()" title="Fetch lyrics for the current track">⟳ Fetch</button>
          <button class="player-btn" type="button" onclick="previousTrack()" title="Previous">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor">
              <path d="M6 5h2v14H6zM19 6.5v11L9.5 12z"></path>
